int Mark(string name, int value) { Print(name); return value; }
class Pair {
    public int A = Mark("field A", 1);
    public long B = Mark("field B", 2);
    public Pair(int first, long second = 9) { Print("ctor"); A = first; B = second; }
    public Pair(string name) { Print(name); }
    public long Sum(int extra = 0) => A + B + extra;
}
Pair Get(Pair value) { Print("receiver"); return value; }
void Main() {
    var pair = new Pair(second: Mark("second", 20), first: Mark("first", 10));
    Print(Get(pair).Sum(extra: Mark("argument", 3)));
    Print(new Pair(4).Sum());
    Print(new Pair("overload").Sum());
}
